// MnemosServiceServer is the server API for MnemosService service.
// All implementations must embed UnimplementedMnemosServiceServer
// for forward compatibility.
//
// MnemosService provides the gRPC API surface for the Mnemos knowledge
// registry. It mirrors the HTTP REST API at /v1/* with equivalent
// operations for episodes, beliefs, associations, embeddings, and metrics.
type MnemosServiceServer interface {
	// Health returns the service health status. Deep probes are available
	// via the detailed field.
	Health(context.Context, *HealthRequest) (*HealthResponse, error)
	// ListEpisodes returns a paginated list of all episodes, most recent first.
	ListEpisodes(context.Context, *ListEpisodesRequest) (*ListEpisodesResponse, error)
	// AppendEpisodes writes one or more episodes to the store. Idempotent on
	// duplicate episode IDs.
	AppendEpisodes(context.Context, *AppendEpisodesRequest) (*AppendResponse, error)
	// ListBeliefs returns a paginated list of beliefs with optional type/status
	// filtering. Evidence links are included when include_evidence is true.
	ListBeliefs(context.Context, *ListBeliefsRequest) (*ListBeliefsResponse, error)
	// AppendBeliefs writes beliefs and optionally their evidence links.
	AppendBeliefs(context.Context, *AppendBeliefsRequest) (*AppendResponse, error)
	// ListAssociations returns a paginated list of associations with
	// optional type filtering.
	ListAssociations(context.Context, *ListAssociationsRequest) (*ListAssociationsResponse, error)
	// AppendAssociations writes one or more association edges.
	AppendAssociations(context.Context, *AppendAssociationsRequest) (*AppendResponse, error)
	// ListEmbeddings returns a paginated list of embeddings with optional
	// entity_type filtering.
	ListEmbeddings(context.Context, *ListEmbeddingsRequest) (*ListEmbeddingsResponse, error)
	// AppendEmbeddings writes one or more embedding vectors.
	AppendEmbeddings(context.Context, *AppendEmbeddingsRequest) (*AppendResponse, error)
	// Metrics returns aggregate counts for the knowledge base.
	Metrics(context.Context, *MetricsRequest) (*MetricsResponse, error)
	// ListActions returns recorded operational actions.
	ListActions(context.Context, *ListActionsRequest) (*ListActionsResponse, error)
	// AppendActions writes operational actions idempotently.
	AppendActions(context.Context, *AppendActionsRequest) (*AppendResponse, error)
	// ListOutcomes returns observed action outcomes.
	ListOutcomes(context.Context, *ListOutcomesRequest) (*ListOutcomesResponse, error)
	// AppendOutcomes writes outcomes idempotently. Auto-edges to the
	// parent action are NOT emitted server-side here; that wiring is
	// done by the higher-level CLI/MCP surface and stays out of the
	// raw write path.
	AppendOutcomes(context.Context, *AppendOutcomesRequest) (*AppendResponse, error)
	// ListSchemas returns synthesised schemas.
	ListSchemas(context.Context, *ListSchemasRequest) (*ListSchemasResponse, error)
	// AppendSchemas writes schemas idempotently (UPSERT on id refreshes
	// confidence/last_verified, snapshots prior to schema_versions).
	AppendSchemas(context.Context, *AppendSchemasRequest) (*AppendResponse, error)
	// ListDecisions returns recorded decisions.
	ListDecisions(context.Context, *ListDecisionsRequest) (*ListDecisionsResponse, error)
	// AppendDecisions writes decisions idempotently.
	AppendDecisions(context.Context, *AppendDecisionsRequest) (*AppendResponse, error)
	// ListReflexes returns synthesised or hand-authored reflexes.
	ListReflexes(context.Context, *ListReflexesRequest) (*ListReflexesResponse, error)
	// AppendReflexes writes reflexes idempotently.
	AppendReflexes(context.Context, *AppendReflexesRequest) (*AppendResponse, error)
	// ListGlobalSchemas returns the schemas promoted to the shared global tier
	// (ADR 0011/0012) — a different entity from ListSchemas, which returns this
	// tenant's schemas. The same records as REST GET /v1/schemas. status is
	// optional (pending | active); anything else is INVALID_ARGUMENT.
	ListGlobalSchemas(context.Context, *ListGlobalSchemasRequest) (*ListGlobalSchemasResponse, error)
	// --- Incidents (parity with REST /v1/incidents) ---
	// OpenIncident records an incident. Requires claims:write; a blank title or
	// unknown severity is INVALID_ARGUMENT.
	OpenIncident(context.Context, *OpenIncidentRequest) (*Incident, error)
	// ListIncidents returns incidents, optionally by severity and/or status.
	ListIncidents(context.Context, *ListIncidentsRequest) (*ListIncidentsResponse, error)
	// GetIncident returns one incident; an unknown id is NOT_FOUND.
	GetIncident(context.Context, *GetIncidentRequest) (*Incident, error)
	// ResolveIncident marks an incident resolved. Requires claims:write; an
	// unknown id is NOT_FOUND and writes nothing.
	ResolveIncident(context.Context, *ResolveIncidentRequest) (*Incident, error)
	// WhyWereWeWrong is the post-incident analysis: the incident, its
	// root-cause belief's provenance and the decisions linked to it.
	WhyWereWeWrong(context.Context, *WhyWereWeWrongRequest) (*WhyWereWeWrongResponse, error)
	// ListEntityAssociations returns polymorphic cross-entity edges.
	ListEntityAssociations(context.Context, *ListEntityAssociationsRequest) (*ListEntityAssociationsResponse, error)
	// AppendEntityAssociations writes polymorphic edges idempotently.
	AppendEntityAssociations(context.Context, *AppendEntityAssociationsRequest) (*AppendResponse, error)
	// --- Connected brain (cognitive layer; parity with HTTP /v1/who-knows etc.) ---
	// WhoKnows ranks the workers whose memory best matches a query.
	WhoKnows(context.Context, *WhoKnowsRequest) (*WhoKnowsResponse, error)
	// KnowledgeGaps lists the store's highest-value open questions.
	KnowledgeGaps(context.Context, *KnowledgeGapsRequest) (*KnowledgeGapsResponse, error)
	// Calibration reports how well stated confidence tracks reality.
	Calibration(context.Context, *CalibrationRequest) (*CalibrationResponse, error)
	// Hypercorrections lists established beliefs a newer belief contradicts.
	Hypercorrections(context.Context, *HypercorrectionsRequest) (*HypercorrectionsResponse, error)
	// Recombinations lists topically-similar-but-unlinked belief pairs.
	Recombinations(context.Context, *RecombinationsRequest) (*RecombinationsResponse, error)
	// AnalogousBeliefs returns the beliefs most structurally analogous to one.
	AnalogousBeliefs(context.Context, *AnalogousBeliefsRequest) (*AnalogousBeliefsResponse, error)
	// --- Belief CRUD (cognitive layer; parity with HTTP GET /v1/claims/{id} etc.) ---
	// GetBelief returns a single belief's full detail.
	GetBelief(context.Context, *GetBeliefRequest) (*BeliefDetail, error)
	// SetBeliefLifecycle transitions a belief (candidate | promoted | superseded).
	SetBeliefLifecycle(context.Context, *SetBeliefLifecycleRequest) (*SetBeliefLifecycleResponse, error)
	// RetractEpisode withdraws an episode as evidence (ADR 0037): beliefs it
	// alone supported are retracted, beliefs with other live evidence are
	// rescored, and the impact is reported. The same operation as REST
	// POST /v1/episodes/{id}/retract and the retract_episode MCP tool. Requires
	// claims:write; an unknown episode, or one outside the token's runs, is
	// NOT_FOUND. Repeating it writes nothing and returns the stored record with
	// already_retracted set.
	RetractEpisode(context.Context, *RetractEpisodeRequest) (*RetractEpisodeResponse, error)
	// UnretractEpisode clears an episode's retraction (ADR 0037 §8): beliefs
	// the retraction deprecated return to their earlier status unless something
	// else changed them since (reported as skipped, with the reason), and
	// beliefs it rescored get the episode back as evidence. The same operation
	// as REST POST /v1/episodes/{id}/unretract and the unretract_episode MCP
	// tool. Requires claims:write; an unknown episode, or one outside the
	// token's runs, is NOT_FOUND; one that was never retracted is
	// FAILED_PRECONDITION. Repeating it writes nothing and returns the stored
	// record with already_unretracted set.
	UnretractEpisode(context.Context, *UnretractEpisodeRequest) (*UnretractEpisodeResponse, error)
	// ListEpisodeDependencies lists an episode's source dependencies (ADR
	// 0038): what it cites, copies or derives from, what depends on it, and its
	// citations that named no stored episode yet. include_removed also returns
	// dependencies removed by hand. The same read as REST GET
	// /v1/episodes/{id}/dependencies and the episode_dependencies MCP tool. An
	// unknown episode, or one outside the token's runs, is NOT_FOUND.
	ListEpisodeDependencies(context.Context, *ListEpisodeDependenciesRequest) (*ListEpisodeDependenciesResponse, error)
	// DeclareEpisodeDependency records by hand that an episode depends on
	// another and rescores the dependent episode's beliefs; it never retracts
	// anything (source_retracted reports the source's state). A removed
	// dependency is revived. The same operation as REST POST
	// /v1/episodes/{id}/dependencies and the declare_episode_dependency MCP
	// tool. Requires claims:write; an unknown episode is NOT_FOUND, a bad kind,
	// note or pair INVALID_ARGUMENT, a live dependency ALREADY_EXISTS.
	DeclareEpisodeDependency(context.Context, *DeclareEpisodeDependencyRequest) (*EpisodeDependencyChange, error)
	// RemoveEpisodeDependency marks a dependency removed, with an optional
	// reason (kept as a tombstone, so detection cannot re-add it; a revival
	// keeps it in the edit history) and rescores the dependent episode's
	// beliefs; it never un-retracts anything. The same operation as REST
	// DELETE /v1/episodes/{id}/dependencies/{depends_on} and the
	// remove_episode_dependency MCP tool. Requires claims:write; a pair with no
	// live dependency is NOT_FOUND, an over-long reason INVALID_ARGUMENT.
	RemoveEpisodeDependency(context.Context, *RemoveEpisodeDependencyRequest) (*EpisodeDependencyChange, error)
	// Classify reports whether a candidate statement fits established knowledge or is novel.
	Classify(context.Context, *ClassifyRequest) (*ClassifyResponse, error)
	// GetDecision returns a single recorded decision by id.
	GetDecision(context.Context, *GetDecisionRequest) (*Decision, error)
	// --- Advanced recall (cognitive layer; parity with HTTP GET /v1/recall) ---
	// Recall runs advanced retrieval; mode selects the epistemic-honesty variant
	// (sufficiency | effort | context | conflicts | iterative).
	Recall(context.Context, *RecallRequest) (*RecallResponse, error)
	// --- Working memory + skill loop + temporal (cognitive layer) ---
	// GetBlocks returns an owner's working-memory blocks.
	GetBlocks(context.Context, *GetBlocksRequest) (*GetBlocksResponse, error)
	// SetBlock sets or appends a working-memory block.
	SetBlock(context.Context, *SetBlockRequest) (*SetBlockResponse, error)
	// Synthesize runs a synthesis pass (actions -> schemas + reflexes).
	Synthesize(context.Context, *SynthesizeRequest) (*SynthesizeResponse, error)
	// Timeline returns episodes on the temporal timeline.
	Timeline(context.Context, *TimelineRequest) (*TimelineResponse, error)
	// Signals returns detected temporal patterns.
	Signals(context.Context, *SignalsRequest) (*SignalsResponse, error)
	// --- Ingest, search, passages, context, prediction and brain reads
	// (capability-registry parity with REST / MCP / the Go library) ---
	// ProcessText runs raw text through ingest -> extract -> relate -> persist,
	// the same pipeline as REST POST /v1/process and the process_text MCP tool.
	ProcessText(context.Context, *ProcessTextRequest) (*ProcessTextResponse, error)
	// Search is hybrid belief search with filters (REST /v1/search, MCP
	// query_knowledge): the same recall path through query.Engine.Recall.
	Search(context.Context, *SearchRequest) (*SearchResponse, error)
	// Passages returns the stored episode passages that best match a query (BM25).
	Passages(context.Context, *PassagesRequest) (*PassagesResponse, error)
	// ContextBlock renders a run's agent-ready context block (REST /v1/context).
	ContextBlock(context.Context, *ContextBlockRequest) (*ContextBlockResponse, error)
	// PredictiveError reports hierarchical prediction error (ADR 0017).
	PredictiveError(context.Context, *PredictiveErrorRequest) (*PredictiveErrorResponse, error)
	// BrainHealth reports the unified brain-health verdict (ADR 0019).
	BrainHealth(context.Context, *BrainHealthRequest) (*BrainHealthResponse, error)
	// SetExpectation attaches (or replaces) a forward prediction on a belief.
	SetExpectation(context.Context, *SetExpectationRequest) (*Expectation, error)
	// GetExpectation reads a belief's expectation; NotFound when it has none.
	GetExpectation(context.Context, *GetExpectationRequest) (*Expectation, error)
	// RecordObservation records the observed value for a belief's expectation.
	RecordObservation(context.Context, *RecordObservationRequest) (*Expectation, error)
	// ReconcileExpectations closes every observed prediction into a
	// validates/refutes verdict.
	ReconcileExpectations(context.Context, *ReconcileExpectationsRequest) (*ReconcileExpectationsResponse, error)
	// --- Belief writes, governance and per-belief reads (one implementation
	// with REST, MCP and the Go library: internal/beliefops and the Memory
	// facade). An unknown belief is NOT_FOUND, a malformed request
	// INVALID_ARGUMENT. ---
	// RememberFact stores one fact as a belief, recording each evidence string
	// as an observation episode it links to (REST POST /v1/facts, MCP
	// remember's library twin). Requires claims:write; a run-scoped token is
	// PERMISSION_DENIED because the episodes carry no run.
	RememberFact(context.Context, *RememberFactRequest) (*RememberFactResponse, error)
	// ScanBeliefs returns beliefs valid within a time window, ordered by
	// valid_from (REST GET /v1/scan). A run-scoped token is PERMISSION_DENIED:
	// a scan spans every run.
	ScanBeliefs(context.Context, *ScanBeliefsRequest) (*ScanBeliefsResponse, error)
	// DeprecateBelief marks a belief deprecated (MCP memory_deprecate / forget,
	// REST POST /v1/beliefs/{id}/deprecate). Requires claims:write.
	DeprecateBelief(context.Context, *DeprecateBeliefRequest) (*BeliefStatusChange, error)
	// UpdateBelief rewrites a belief's text and optionally its confidence
	// (MCP update, REST POST /v1/beliefs/{id}/update). Requires claims:write.
	UpdateBelief(context.Context, *UpdateBeliefRequest) (*BeliefRevision, error)
	// ResolveDissonance settles two contradicting beliefs: winner resolved,
	// loser deprecated (MCP memory_resolve_dissonance, REST POST
	// /v1/beliefs/{id}/resolve). Requires claims:write.
	ResolveDissonance(context.Context, *ResolveDissonanceRequest) (*ResolveDissonanceResponse, error)
	// EscalateBelief asks for a human decision on a belief and returns the
	// escalation; it writes nothing (MCP memory_escalate, REST POST
	// /v1/beliefs/{id}/escalate). Requires claims:write.
	EscalateBelief(context.Context, *EscalateBeliefRequest) (*BeliefEscalation, error)
	// VerifyBelief re-verifies a belief against fresh evidence (MCP
	// memory_promote, REST POST /v1/beliefs/{id}/verify). Requires
	// promote:global.
	VerifyBelief(context.Context, *VerifyBeliefRequest) (*VerifyBeliefResponse, error)
	// RecordBeliefFeedback records a helpful/unhelpful vote (MCP
	// record_feedback, REST POST /v1/beliefs/{id}/feedback). Requires
	// claims:write.
	RecordBeliefFeedback(context.Context, *RecordBeliefFeedbackRequest) (*BeliefFeedback, error)
	// BeliefProvenance explains how a belief's trust was computed (REST GET
	// /v1/beliefs/{id}/provenance).
	BeliefProvenance(context.Context, *BeliefProvenanceRequest) (*BeliefProvenance, error)
	// BeliefHistory returns a belief's version chain newest first (REST GET
	// /v1/beliefs/{id}/history).
	BeliefHistory(context.Context, *BeliefHistoryRequest) (*BeliefHistoryResponse, error)
	mustEmbedUnimplementedMnemosServiceServer()
}

